{"file_text": "@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <ChannelList Channels="_channels"
                 SelectedChannelId="_selectedChannel?.Id"
                 OnChannelSelected="SelectChannel" />

    @if (_selectedChannel is not null)
    {
        <MessageArea ChannelName="@_selectedChannel.Name"
                     ChannelDescription="@_selectedChannel.Description"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSend="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    }

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnReply="SendThreadReply"
                     OnClose="CloseThread" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private bool _isLoadingMore;

    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private bool IsThreadOpen => _threadRootMessage is not null;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _threadRootMessage = null;
        _threadReplies = [];
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh unread count for the selected channel
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null || _isLoadingMore) return;

        _isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            _messages.InsertRange(0, olderMessages);
            BuildThreadSummaries();
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is not null)
        {
            var threadMessages = await ChatService.GetThreadAsync(messageId);
            _threadReplies = threadMessages.Where(m => m.Id != messageId).ToList();
        }
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
        }
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = _messages.Where(r => r.ReplyToId == m.Id).ToList();
                return replies.Count > 0
                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
                    : null;
            })
            .Where(t => t is not null)
            .Cast<ThreadSummary>()
            .ToList();
    }
}
