+        var olderMessages = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
+        if (olderMessages.Count > 0)
+        {
+            _messages.InsertRange(0, olderMessages);
+            BuildThreadSummaries();
+        }
+        _isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (_selectedChannel is null) return;
+        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
+        _messages.Add(message);
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
+        if (_threadRootMessage is not null)
+        {
+            var threadMessages = await ChatService.GetThreadAsync(messageId);
+            _threadReplies = threadMessages.Where(m => m.Id != messageId).ToList();
+        }
+    }
+
+    private void CloseThread()
+    {
+        _threadRootMessage = null;
+        _threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_selectedChannel is null || _threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
+        _threadReplies.Add(reply);
+        BuildThreadSummaries();
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to show updated reactions
+        if (_selectedChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
+        }
+    }
+
+    private void BuildThreadSummaries()
+    {
+        _threadSummaries = _messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m =>
+            {
+                var replies = _messages.Where(r => r.ReplyToId == m.Id).ToList();
+                return replies.Count > 0
+                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
+                    : null;
+            })
+            .Where(t => t is not null)
+            .Cast<ThreadSummary>()
+            .ToList();
+    }
+}
